import{Z as s,e as o,f as i,a0 as e}from"./chunks/framework.DmpHOl9T.js";const g=JSON.parse('{"title":"Submission Limits","description":"","frontmatter":{},"headers":[],"relativePath":"forms/submission-limits.md","filePath":"forms/submission-limits.md","lastUpdated":1781691156000}'),r={name:"forms/submission-limits.md"};function n(a,t,m,l,d,h){return o(),i("div",null,[...t[0]||(t[0]=[e('<h1 id="submission-limits" tabindex="-1">Submission Limits <a class="header-anchor" href="#submission-limits" aria-label="Permalink to &quot;Submission Limits&quot;">​</a></h1><p>Submission limits control how many entries a form accepts. They are a <strong>business rule</strong> — for contests, registrations, surveys with quotas, and similar cases where you need a hard cap.</p><p>Configure them per form under <strong>Formie → Forms → {form} → Settings → Behaviour → Submission Limits</strong>.</p><p>Submission limits are separate from <a href="/forms/spam-protection">Spam Protection</a> throttling, which marks rapid or flood submissions as spam. They are also separate from <strong>Availability</strong> settings on the same Behaviour tab, which control whether the form is shown at all.</p><h2 id="how-limits-work" tabindex="-1">How Limits Work <a class="header-anchor" href="#how-limits-work" aria-label="Permalink to &quot;How Limits Work&quot;">​</a></h2><p>Turn on <strong>Limit Submissions</strong>, then choose <strong>Apply Limit To</strong>:</p><table tabindex="0"><thead><tr><th>Scope</th><th>What it counts</th><th>When the limit is reached</th></tr></thead><tbody><tr><td><strong>All submissions for this form</strong></td><td>Every submission stored for the form</td><td>The form closes and shows your limit message</td></tr><tr><td><strong>Per IP address</strong></td><td>Submissions from the same IP for this form</td><td>The form stays open; the visitor sees a validation error</td></tr><tr><td><strong>Per logged-in user</strong></td><td>Submissions linked to the same Craft user for this form</td><td>The form stays open; the visitor sees a validation error</td></tr></tbody></table><p>Set <strong>Allow</strong> to the number of submissions permitted for the chosen scope, and choose a period (<strong>all time</strong>, <strong>per day</strong>, <strong>per week</strong>, <strong>per month</strong>, or <strong>per year</strong>).</p><p>Use <strong>Message</strong> to customise what visitors see when a limit is reached.</p><h3 id="per-logged-in-user-limits" tabindex="-1">Per Logged-in User Limits <a class="header-anchor" href="#per-logged-in-user-limits" aria-label="Permalink to &quot;Per Logged-in User Limits&quot;">​</a></h3><p>Per-user limits require Formie to know who submitted. Enable <strong>Collect User</strong> under <strong>Settings → Privacy</strong> on the form (or preset it in <strong>Formie → Settings → Defaults</strong> or a form group’s <strong>Form Defaults</strong> tab).</p><p>Anonymous visitors are not counted toward a per-user limit.</p><h3 id="per-ip-address-limits" tabindex="-1">Per IP Address Limits <a class="header-anchor" href="#per-ip-address-limits" aria-label="Permalink to &quot;Per IP Address Limits&quot;">​</a></h3><p>Per-IP limits work best when <strong>Collect IP</strong> is enabled under <strong>Settings → Privacy</strong>, so Formie can reliably attribute submissions. If IP collection is off, behaviour may be less predictable depending on your setup.</p><h2 id="availability-vs-submission-limits-vs-throttling" tabindex="-1">Availability vs Submission Limits vs Throttling <a class="header-anchor" href="#availability-vs-submission-limits-vs-throttling" aria-label="Permalink to &quot;Availability vs Submission Limits vs Throttling&quot;">​</a></h2><p>Formie splits “who can submit and how often” across three layers:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Where</th><th>Purpose</th><th>Typical outcome</th></tr></thead><tbody><tr><td><strong>Availability</strong></td><td>Form → Settings → Behaviour</td><td>Schedule, manual disable, require login</td><td>Form hidden or unavailable message</td></tr><tr><td><strong>Submission limits</strong></td><td>Form → Settings → Behaviour</td><td>Entry caps by form, IP, or user</td><td>Form closes (form scope) or validation error (IP/user scope)</td></tr><tr><td><strong>Submission throttling</strong></td><td><strong>Settings → Spam Protection</strong></td><td>Abuse and flood protection</td><td>Submission marked as spam</td></tr></tbody></table><p>Use <strong>Availability</strong> when the form should not be shown yet, or only to certain audiences.</p><p>Use <strong>Submission limits</strong> when you need a defined quota — one entry per person, 100 total responses, and so on.</p><p>Use <strong>Submission throttling</strong> when you need sitewide or rapid-repeat protection during an attack. Throttling does not replace per-form caps; it complements them.</p><h3 id="ip-wait-time-vs-ip-count-limits" tabindex="-1">IP Wait Time vs IP Count Limits <a class="header-anchor" href="#ip-wait-time-vs-ip-count-limits" aria-label="Permalink to &quot;IP Wait Time vs IP Count Limits&quot;">​</a></h3><p>These sound similar but behave differently:</p><ul><li><strong>IP submission throttling</strong> (Spam Protection) — minimum <strong>wait time</strong> between two submissions from the same IP on the same form. Failed checks are treated as spam.</li><li><strong>Per IP address</strong> submission limits (form settings) — maximum <strong>count</strong> of submissions from an IP over a period. Failed checks show your limit message as a normal validation error.</li></ul><p>You can use both on the same form when it makes sense: throttling slows bots; count limits enforce your entry policy.</p><h2 id="form-groups" tabindex="-1">Form Groups <a class="header-anchor" href="#form-groups" aria-label="Permalink to &quot;Form Groups&quot;">​</a></h2><p><a href="/forms/form-groups">Form groups</a> do not enforce submission limits across every form in a group. Limits remain <strong>per form</strong>.</p><p>Groups can still help teams that rely on limits:</p><ul><li><strong>Allowed submission statuses</strong> (group <strong>General</strong> tab) restricts which statuses forms in the group may use.</li><li><strong>Form Defaults</strong> can preset <strong>Collect User</strong> or <strong>Collect IP</strong> so new forms in the group are ready for per-user or per-IP limits.</li></ul><h2 id="editing-existing-submissions" tabindex="-1">Editing Existing Submissions <a class="header-anchor" href="#editing-existing-submissions" aria-label="Permalink to &quot;Editing Existing Submissions&quot;">​</a></h2><p>Changing or deleting an existing submission does not consume an additional limit slot. Limits apply when <strong>creating</strong> new submissions.</p>',30)])])}const p=s(r,[["render",n]]);export{g as __pageData,p as default};
